  100	    /**
  101	     * The gap between one planet's order and the next in a login, the way a player clicks through
  102	     * planets. It also keeps a session's intents from reaching the workers in the same instant, where
  103	     * all but one lose the per-player lock and wait out a retry.
  104	     */
  105	    private const SECONDS_BETWEEN_PLANETS = 20;
  106	
  107	    public function __construct(
  108	        private QueueableBuildingPlanner $queueableBuildingPlanner,
  109	        private QueueableUnitPlanner $queueableUnitPlanner,
