  124	    /**
  125	     * Writes the one work item that carries the intent out, keyed by the session's
  126	     * own id: a retried session converges on one action, a later session decides
  127	     * again. The payload is whatever the plan approved, so the schedule and the
  128	     * executor always name the same objective.
  129	     *
  130	     * @param array<string, mixed> $payload
  131	     */
  132	    private function enqueue(AiProfile $profile, AiWorkItem $sessionWorkItem, AiWorkKind $kind, array $payload, ?CarbonImmutable $dueAt = null, string $keySuffix = ''): void
  133	    {
  134	        AiWorkItem::query()->firstOrCreate(
  135	            ['idempotency_key' => 'intent:session:' . $sessionWorkItem->id . $keySuffix],
  136	            [
  137	                'player_id' => $profile->player_id,
  138	                'kind' => $kind,
  139	                'due_at' => $dueAt ?? $this->clock->now(),
  140	                'schedule_generation' => (int) ($sessionWorkItem->schedule_generation ?? 1),
  141	                'state' => AiWorkState::Pending,
  142	                'payload' => $payload,
  143	            ],
  144	        );
  145	    }
  146	
  147	    public function handle(AiProfile $profile, AiWorkItem $sessionWorkItem, DecisionTrace $trace): void
  148	    {
  149	        // Every case is listed: adding a capability means deciding here where it is executed, and
  150	        // a capability with no executor must not be published to begin with.
  151	        $type = $trace->selected->candidate->type;
  152	        // The unit plan is read here, before the building steps are enqueued, because one order's
  153	        // placement decides whether it happens at all: the first wall of a planet that stands bare
  154	        // beside a walled sibling is priced against the balance those steps spend, so the host
  155	        // refuses it and the planet stays naked session after session (QUAL-003).
  156	        //
  157	        // It is read for every chosen action, not only QueueUnits: the wall candidate is one of a
  158	        // dozen and the economy's habit outranks it in most logins, so waiting for the sessions the
  159	        // engine happens to pick the shipyard left the bare planet naked while the account kept
  160	        // colonising (measured live 2 Oct 2026: 1 planet at zero defence beside a sibling holding
  161	        // 1,746). A login is one wall order whichever action was chosen.
  162	        // The wall's own facility may be refused by the economy in the same login (the planet is saving
  163	        // for its next mine), so the unit plan is asked before the building steps for every chosen
  164	        // action: a bare planet's wall is the one order whose placement decides whether it happens.
  165	        $units = $this->queueableUnitPlanner->plan($profile->player_id);
  166	        $unitsFirst = $units instanceof QueueableUnit && $units->aheadOfEconomy;
  167	
  168	        // The marked wall is written before the building steps, because work falls due in the order
  169	        // it was written and same-instant work keeps that order: written after them, the steps have
  170	        // already spent the balance the wall was priced against, the host refuses it, and the planet
  171	        // stands naked beside its walled sibling again on the next login (QUAL-003).
  172	        //
  173	        // A wall placed on a login that chose something else keeps a key of its own, so the session's
  174	        // own action still owns the primary key: a retried session converges on that action, and the
  175	        // wall is one more order in the login rather than the login's objective.
  176	        if ($unitsFirst) {
  177	            $this->scheduleUnits($profile, $sessionWorkItem, $this->clock->now(), $units, $type === AiCandidateActionType::QueueUnits ? '' : ':wall');
  178	        }
  179	
  180	        // A player refills the build queues and the lab every login before turning to the shipyard or
  181	        // the fleet; choosing a raid, a ship, nothing at all or answering an inbound fleet must not
  182	        // leave a planet idle until the next session. The refill asks the planner, never the decision
  183	        // trace: a planet is buildable exactly when the planner offers it a step -- the same call the
  184	        // cohort read-out makes -- so asking the trace instead lets the two disagree and the account
  185	        // read idle while it had a legal order to place. A planet the planner offers no step for
  186	        // enqueues nothing, so a login with nothing to spend stays quiet.
  187	        // A Save answers first: its intent is written ahead of these steps, so the fleet still moves
  188	        // before the last order lands.
  189	        // An attacked account saves before it builds: work falls due in the order it was written and
  190	        // same-instant work keeps that order, so the save is written here -- ahead of the building
  191	        // steps -- or the stock it moves has already been spent by them and the fleet stays on the
  192	        // ground. The calm save has no such errand and takes the match arm below, after the builds.
  193	        if ($type === AiCandidateActionType::FleetSave && !$this->isCalmSave($type, $trace)) {
  194	            $this->scheduleFleetSave($profile, $sessionWorkItem, $this->clock->now());
  195	        }
  196	
  197	        $economySteps = $this->fillQueues($profile, $sessionWorkItem, ':economy');
  198	
  199	        match ($type) {
  200	            // The queues are already filled by the shared pass above, under the session's own key.
  201	            AiCandidateActionType::Build, AiCandidateActionType::Research => null,
  202	            // The shipyard gets what the buildings leave, so its order waits until they are placed:
  203	            // the host cancels a building it cannot pay for, and a ship order placed first would cause it.
  204	            // A marked wall is already written above; the repeat finds that row and leaves its time.
  205	            AiCandidateActionType::QueueUnits => $this->scheduleUnits($profile, $sessionWorkItem, $this->clock->now()->addSeconds($economySteps * self::SECONDS_BETWEEN_PLANETS), $units),
  206	            AiCandidateActionType::Colonize => $this->scheduleColony($profile, $sessionWorkItem),
  207	            AiCandidateActionType::Expedition => $this->scheduleExpedition($profile, $sessionWorkItem),
  208	            // The ferry moves stock the buildings were priced against, so it waits for them t
